lines=['# Ingresos T2/T3-2024 con origen 2025 en MU2025: contraste de carrera','',f"Fecha de ejecución: {datetime.datetime.now().astimezone().isoformat()}. Hito relacionado: H001-RETENCION-IPSS162.",'','## Objetivo y alcance','','**D.** Revisar la hipótesis de cambio de carrera para las 44 personas de ingreso UMAS T2-2024 y las 44 de T3-2024 encontradas con ANIO_ING_ORI=2025 en MU2025. Son 88 personas distintas entre los dos grupos. Se conservan bases, reglas y denominadores 558/1.150 y 222/124. No se modifica el Excel ni se realiza commit/push.','','## Resultado','','**B/C.** No se confirma que el conjunto se explique por cambios de carrera. En 83 personas coincide el código de carrera observado en DatosAlumnos con COD_CAR en MU2025; cinco tienen otra carrera. Estos cinco tienen además una matrícula UMAS con ingreso 2025 en la carrera de destino. Solo uno está explícitamente marcado 24 - CAMBIO DE CARRERA; los otros cuatro tienen 23 - RETIRO - RETRACTO en la carrera anterior.','','| Grupo observado | Con origen 2025 en MU2025 | Misma carrera observada | Otra carrera observada | Clasificación |','|---|---:|---:|---:|---|']
for x in a:lines.append(f"| 2024-T{x['term']} | 44 | {x['comparacion_carrera']['MISMO_COD_CAR']} | {x['comparacion_carrera']['COD_CAR_DISTINTO']} | B/C |")
lines+=['| Total de personas distintas | 88 | 83 | 5 | B/C |','','## Las cinco trayectorias con diferente carrera','','| Ingreso | Carrera UMAS de ingreso 2024 | Carrera en RAW MU2025 | Código de carrera origen → destino | Situación en carrera anterior | Personas | Clasificación |','|---|---|---|---|---:|---|']
